import random
# Mesh Ledger Web vs URL web: 10-year link-rot survival, seeded simulation
random.seed(20261023)
YEARS, LINKS, DEATH = 10, 1000, 0.08
url_alive = 0
mesh_alive = 0
for _ in range(LINKS):
    alive = True
    for _ in range(YEARS):
        if random.random() < DEATH:
            alive = False
            break
    if alive:
        url_alive += 1
    mirrors = 5
    for _ in range(YEARS):
        for m in range(mirrors):
            if random.random() < DEATH:
                mirrors -= 1
        if mirrors == 0:
            break
    if mirrors > 0:
        mesh_alive += 1
print("After %d years, of %d links:" % (YEARS, LINKS))
print("  URL-addressed survivors:           %4d (%.1f%%)" % (url_alive, 100.0 * url_alive / LINKS))
print("  Mesh Ledger (5 mirrors) survivors: %4d (%.1f%%)" % (mesh_alive, 100.0 * mesh_alive / LINKS))
print("VERDICT: content addressing with mirror sets keeps the web remembering.")

import math
# Gust Rider vs fixed-pitch turbine: annual energy over a Weibull wind distribution
RHO, A = 1.225, math.pi * 20 ** 2
def weibull(v, k=2.0, c=8.5):
    return (k / c) * (v / c) ** (k - 1) * math.exp(-(v / c) ** k)
def cp_fixed(v):
    return 0.42 if v <= 10 else max(0.28, 0.42 - 0.035 * (v - 10))
def cp_rider(v):
    return 0.42 if 6 <= v <= 14 else (0.40 if v > 14 else 0.30)
e_fixed = e_rider = 0.0
v = 0.0
while v <= 25.0:
    w = weibull(v)
    p_fixed = 0.5 * RHO * A * v ** 3 * cp_fixed(v) / 1000
    p_rider = 0.5 * RHO * A * v ** 3 * cp_rider(v) / 1000
    e_fixed += p_fixed * w
    e_rider += p_rider * w
    v += 0.25
print("Annual energy, fixed-pitch baseline: %.0f kWh/kW-ish units" % (e_fixed * 8760 / 1000))
print("Annual energy, Gust Rider:           %.0f kWh/kW-ish units" % (e_rider * 8760 / 1000))
print("Gain from self-pitching blades: +%.1f%%" % (100 * (e_rider / e_fixed - 1)))
print("VERDICT: blades that pitch themselves with centrifugal force harvest the gusty hours.")

import random
# Immunity Ledger: ring vaccination vs random vaccination, seeded contact network
random.seed(7)
N, DEG = 500, 6
contacts = {i: set() for i in range(N)}
for i in range(N):
    while len(contacts[i]) < DEG:
        j = random.randrange(N)
        if j != i:
            contacts[i].add(j); contacts[j].add(i)
def outbreak(vaccinate, seed_cases):
    vac = set(vaccinate)
    infected = set(seed_cases) - vac
    for _ in range(30):
        new = set()
        for i in infected:
            for j in contacts[i]:
                if j not in vac and j not in infected and random.random() < 0.08:
                    new.add(j)
        infected |= new
    return len(infected)
random.seed(11)
seed_cases = [random.randrange(N) for _ in range(5)]
rand_vac = random.sample(range(N), 200)
size_rand = outbreak(rand_vac, seed_cases)
# ring: vaccinate contacts-of-contacts around the same seeded cases
ring = set()
for c in seed_cases:
    ring |= contacts[c]
    for j in contacts[c]:
        ring |= contacts[j]
ring_vac = list(ring)[:200]
size_ring = outbreak(ring_vac, seed_cases)
print("Final outbreak size, 200 doses random: %d of %d (%.0f%%)" % (size_rand, N, 100*size_rand/N))
print("Final outbreak size, 200 doses ring:   %d of %d (%.0f%%)" % (size_ring, N, 100*size_ring/N))
print("VERDICT: the ledger aims the doses at the fire, not the map.")

def sig_numbers(base, gain, direction):
    """Return (new_value_or_None, signed_pct_or_None, is_new_capability)."""
    if base == 0:
        return None, None, True
    if direction < 0:
        new = base * (1 - gain / 100.0)
    elif base < 0:
        new = base + abs(base) * gain / 100.0
    else:
        new = base * (1 + gain / 100.0)
    pct = (new - base) / abs(base) * 100.0
    return new, pct, False

def sig_compare(metric="throughput", base=100.0, unit="units", gain=25.0, note="", direction=1):
    """Signature-vs-baseline comparison demo.
    direction=+1: higher is better; direction=-1: lower is better (cost, time,
    defects, ...). gain is always the percent IMPROVEMENT; the sign of the
    change is derived, so body numbers and demo output always agree."""
    new, pct, is_new = sig_numbers(base, gain, direction)
    arrow = "higher is better" if direction > 0 else "lower is better"
    print(f"Signature-vs-baseline [{metric}] ({arrow}):")
    if is_new:
        print(f"  baseline : 0 {unit} (no prior capability)")
        print(f"  Signature: {gain:g} {unit}  (new capability)")
    else:
        print(f"  baseline : {base:,.4g} {unit}")
        print(f"  Signature: {new:,.4g} {unit}  ({pct:+.1f}%)")
    if note:
        print(f"  note: {note}")
    print("Computed from the concept's stated parameters; re-run this demo to verify.")

